<?php
$date=(string)($_GET['data']??date('Y-m-d'));
$dt=DateTimeImmutable::createFromFormat('!Y-m-d',$date);if(!$dt||$dt->format('Y-m-d')!==$date)$date=date('Y-m-d');
$stmt=db()->prepare('SELECT f.*,e1.cidade origem,e1.uf origem_uf,e2.cidade destino,e2.uf destino_uf,t.nome transportador, (SELECT COALESCE(SUM(fi.quantidade),0) FROM frete_itens fi WHERE fi.frete_id=f.id) AS itens FROM fretes f JOIN enderecos e1 ON e1.id=f.origem_id JOIN enderecos e2 ON e2.id=f.destino_id JOIN transportadores t ON t.id=f.transportador_id WHERE f.data_frete=? ORDER BY f.id DESC');$stmt->execute([$date]);$records=$stmt->fetchAll();$sum=array_sum(array_column($records,'valor_frete'));
?>
<section class="panel"><div class="panel-header"><div><h2>Relatório diário de fretes</h2><p>Filtre os registros por data e faça o download em CSV</p></div></div><form class="report-filter" method="get"><input type="hidden" name="page" value="relatorios"><label>Data do relatório<input class="form-control" type="date" name="data" value="<?=h($date)?>" required></label><button class="btn btn-purple" type="submit">Consultar</button><a class="btn btn-outline-purple" href="index.php?page=relatorios&amp;export=csv&amp;data=<?=h($date)?>">↓ &nbsp;Baixar CSV</a></form>
<div class="report-kpis"><div><span>Fretes na data</span><strong><?=count($records)?></strong></div><div><span>Valor total</span><strong><?=money($sum)?></strong></div><div><span>Itens transportados</span><strong><?=array_sum(array_column($records,'itens'))?></strong></div></div>
<div class="table-responsive"><table class="table app-table"><thead><tr><th>Frete</th><th>Data</th><th>Origem</th><th>Destino</th><th>Transportador</th><th>Itens</th><th>Valor</th></tr></thead><tbody>
<?php foreach($records as $r):?><tr><td><b>#<?=$r['id']?></b></td><td><?=date('d/m/Y',strtotime($r['data_frete']))?></td><td><?=h($r['origem'].'/'.$r['origem_uf'])?></td><td><?=h($r['destino'].'/'.$r['destino_uf'])?></td><td><?=h($r['transportador'])?></td><td><?=h($r['itens'])?></td><td><?=money($r['valor_frete'])?></td></tr><?php endforeach;?>
<?php if(!$records):?><tr><td colspan="7" class="empty-state">Nenhum frete encontrado para <?=date('d/m/Y',strtotime($date))?>.</td></tr><?php endif;?></tbody></table></div></section>
